INSERT INTO tours (id, code, title, thumbnail_url, agency_name, airline_id, origin_city, destination_city, duration_days, duration_nights, duration_text, departure_time, flight_duration, aircraft_type, price, included_services, excluded_services, itinerary_json, featured) VALUES
(1, 'TOUR-DAD-01', 'Tour Đà Nẵng - Cầu Vàng Bà Nà Hills - Phố Cổ Hội An', 'https://images.unsplash.com/photo-1559592413-7cec4d0cae2b?w=600&h=400&fit=crop', 'Vietjet Holidays', 1, 'TP. Hồ Chí Minh', 'Đà Nẵng', 4, 3, '4N3Đ', '06:30', '1 giờ 20 phút', 'Airbus A321neo', 4590000, 'Vé máy bay khứ hồi Vietjet, Khách sạn 4 sao trung tâm biển Mỹ Khê, Vé cáp treo Bà Nà Hills, Ăn buffet tiêu chuẩn, Xe du lịch đưa đón VIP, Hướng dẫn viên suốt tuyến, Bảo hiểm du lịch 50.000.000đ', 'Chi phí cá nhân, Giặt ủi, Nước uống ngoài chương trình, Tiền bồi dưỡng hướng dẫn viên', '[{"day":1,"title":"TP.HCM - Đà Nẵng - Bán Đảo Sơn Trà - Ngũ Hành Sơn","desc":"Đáp chuyến bay sáng đến Đà Nẵng, viếng Chùa Linh Ứng Sơn Trà ngắm biển Mỹ Khê, tham quan danh thắng Ngũ Hành Sơn làng đá mỹ nghệ Non Nước."},{"day":2,"title":"Chinh Phục Tiên Cảnh Bà Nà Hills - Check-in Cầu Vàng Huyền Thoại","desc":"Trải nghiệm tuyến cáp treo đạt kỷ lục thế giới, dạo bước trên Cầu Vàng khổng lồ, vui chơi Fantasy Park và thưởng thức đại tiệc buffet hơn 100 món."},{"day":3,"title":"Phố Cổ Hội An Lung Linh Sắc Màu - Thả Hoa Đăng Sông Hoài","desc":"Dạo bước Chùa Cầu Nhật Bản, Hội quán Phúc Kiến, nhà cổ Phùng Hưng. Thưởng thức đặc sản Cao Lầu, thả đèn hoa đăng lung linh cầu may trên dòng sông Hoài."},{"day":4,"title":"Chợ Hàn Đà Nẵng - Mua Sắm Đặc Sản - Bay Về TP.HCM","desc":"Tự do tắm biển Mỹ Khê buổi sớm, ghé Chợ Hàn mua chả bò, mực một nắng, bánh khô mè. Xe tiễn sân bay Đà Nẵng đáp chuyến bay về lại TP.HCM."}]', 1),
