(2, 'TOUR-PQC-02', 'Tour Phú Quốc - Thành Phố Không Ngủ Grand World - Cáp Treo Hòn Thơm', 'https://images.unsplash.com/photo-1583417319070-4a69db38a482?w=600&h=400&fit=crop', 'Vietjet Holidays', 1, 'TP. Hồ Chí Minh', 'Phú Quốc', 3, 2, '3N2Đ', '09:15', '1 giờ 05 phút', 'Airbus A321neo', 3990000, 'Vé máy bay khứ hồi Vietjet, Resort 5 sao mặt biển có hồ bơi vô cực, Vé cáp treo vượt biển Hòn Thơm 2 chiều, Vé Grand World, 02 bữa buffet sáng + 04 bữa chính hải sản', 'Chi phí các trò chơi có tính phí riêng tại VinWonders, Chi phí quầy bar cá nhân', '[{"day":1,"title":"TP.HCM - Đảo Ngọc Phú Quốc - Sunset Sanato Ngắm Hoàng Hôn","desc":"Bay thẳng đến Phú Quốc, nhận phòng resort 5 sao. Chiều ghé Sunset Sanato check-in biểu tượng đầu người chia đôi và voi chân dài ngắm hoàng hôn rực rỡ."},{"day":2,"title":"Trải Nghiệm Cáp Treo Vượt Biển Hòn Thơm - Grand World Không Ngủ","desc":"Đi tuyến cáp treo vượt biển dài nhất thế giới sang Hòn Thơm, tắm biển Bãi Trào. Tối khám phá kênh đào Venice thu nhỏ tại Grand World và xem show Sắc Màu Venice."},{"day":3,"title":"Làng Chài Hàm Ninh - Chợ Đêm Dương Đông - Mua Đặc Sản Bay Về","desc":"Tham quan vườn tiêu Suối Đá, nhà thùng nước mắm truyền thống Phú Quốc, trang trại ngọc trai. Mua quà đặc sản và xe tiễn đoàn ra sân bay về lại TP.HCM."}]', 1),

(3, 'TOUR-HAN-03', 'Tour Hành Trình Di Sản: Hà Nội - Kỳ Quan Vịnh Hạ Long - Sapa Fansipan', 'https://images.unsplash.com/photo-1528127269322-539801943592?w=600&h=400&fit=crop', 'Vietnam Airlines Tour', 2, 'TP. Hồ Chí Minh', 'Hà Nội', 5, 4, '5N4Đ', '08:30', '2 giờ 15 phút', 'Boeing 787-9 Dreamliner', 6890000, 'Vé máy bay khứ hồi Vietnam Airlines 23kg ký gửi, Du thuyền 5 sao vịnh Hạ Long, Khách sạn 4 sao trung tâm Sapa, Vé cáp treo Fansipan Nóc Nhà Đông Dương, Toàn bộ bữa ăn chất lượng cao', 'Vé tàu hỏa leo núi Mường Hoa, Đồ uống cá nhân trong bữa ăn', '[{"day":1,"title":"TP.HCM - Thủ Đô Hà Nội Nghìn Năm Văn Hiến - Hồ Gươm 36 Phố Phường","desc":"Đáp chuyến bay Boeing 787 êm ái đến Nội Bài. Tham quan Quảng trường Ba Đình, Lăng Bác, Chùa Một Cột, Hồ Hoàn Kiếm, Đền Ngọc Sơn và dạo 36 phố phường."},{"day":2,"title":"Hà Nội - Du Ngoạn Kỳ Quan Thiên Nhiên Vịnh Hạ Long","desc":"Di chuyển cao tốc đến Hạ Long, lên du thuyền 5 sao thưởng ngoạn Động Thiên Cung, Hòn Gà Chọi, Hòn Đỉnh Hương. Chèo thuyền kayak trên làn nước ngọc bích."},{"day":3,"title":"Hạ Long - Cao Tốc Nội Bài Lào Cai Đến Thị Trấn Sapa Trong Mây","desc":"Khởi hành lên vùng cao Tây Bắc mộng mơ, ngắm cảnh ruộng bậc thang bạt ngàn. Chiều đến Sapa dạo Nhà thờ đá, hồ Sapa và thưởng thức lẩu cá tầm đặc sản."},{"day":4,"title":"Chinh Phục Đỉnh Cao Fansipan 3.143m - Bản Làng Cát Cát","desc":"Lên cáp treo Fansipan chạm tay vào Cột mốc Nóc Nhà Đông Dương. Chiều tham quan Bản Cát Cát của người H''Mông với guồng nước, thác Tiên Sa thơ mộng."},{"day":5,"title":"Chợ Sapa - Mua Đặc Sản Nấm Hương Hạt Dẻ - Bay Về TP.HCM","desc":"Tự do mua sắm thổ cẩm, rượu táo mèo tại chợ Sapa. Khởi hành về sân bay Nội Bài, đáp chuyến bay tối về lại TP. Hồ Chí Minh."}]', 1),

(4, 'TOUR-CXR-04', 'Tour Biển Xanh Nha Trang - Thiên Đường Giải Trí VinWonders - Tắm Khoáng Nóng', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=600&h=400&fit=crop', 'Bamboo Holidays', 4, 'Hà Nội', 'Nha Trang', 3, 2, '3N2Đ', '07:45', '1 giờ 50 phút', 'Airbus A320', 3450000, 'Vé máy bay khứ hồi Bamboo Airways 20kg ký gửi, Khách sạn 4 sao sát bờ biển Trần Phú, Vé trọn gói Công viên chủ đề VinWonders Hòn Tre, Dịch vụ tắm bùn khoáng nóng I-Resort', 'Chi phí lặn biển bình khí chuyên nghiệp, Đồ uống tại Sailing Club', '[{"day":1,"title":"Hà Nội - Nha Trang - Tháp Bà Ponagar - Suối Khoáng Nóng I-Resort","desc":"Bay từ Hà Nội vào Cam Ranh, viếng Tháp Bà Ponagar kiến trúc Chăm cổ kính. Thư giãn ngâm bùn khoáng nóng phục hồi năng lượng và ăn tiệc hải sản tươi ngon."},{"day":2,"title":"Oanh Tạc Quần Thể Vui Chơi Giải Trí Đẳng Cấp VinWonders Hòn Tre","desc":"Đi cano cao tốc sang đảo Hòn Tre, chinh phục Đồi Thử Thách, Vịnh Phao Nổi khổng lồ, Thủy cung với hàng ngàn sinh vật biển và xem show diễn triệu đô Tata Show."},{"day":3,"title":"Du Ngoạn Vịnh Nha Trang - Chợ Đầm Mua Đặc Sản - Bay Về Hà Nội","desc":"Đi tàu ngắm vẻ đẹp Vịnh Nha Trang, ghé Chợ Đầm mua yến sào, chả cá Nha Trang, xoài sấy dẻo. Xe đưa ra sân bay Cam Ranh bay về Hà Nội."}]', 1),

(5, 'TOUR-BKK-05', 'Tour Thái Lan: Bangkok Hiện Đại - Thành Phố Không Ngủ Pattaya - Đảo San Hô', 'https://images.unsplash.com/photo-1508009603885-50cf7c579365?w=600&h=400&fit=crop', 'Vietjet Holidays', 1, 'TP. Hồ Chí Minh', 'Bangkok', 5, 4, '5N4Đ', '11:15', '1 giờ 30 phút', 'Airbus A321neo', 5990000, 'Vé máy bay khứ hồi Vietjet, Khách sạn 4 sao tiêu chuẩn quốc tế, Đại tiệc Buffet tại tòa nhà 86 tầng Baiyoke Sky, Vé xem show diễn nghệ thuật Alcazar hoành tráng, Cano ra Đảo San Hô Koh Larn', 'Tiền bồi dưỡng tài xế và HDV Thái Lan (5$/ngày), Chi phí đổi tiền tệ cá nhân', '[{"day":1,"title":"TP.HCM - Sân Bay Suvarnabhumi Bangkok - Khám Phá Chợ Đêm Jodd Fairs","desc":"Bay thẳng từ SGN đến Bangkok. Xe đón về nhận phòng khách sạn, tối oanh tạc Chợ đêm Jodd Fairs thưởng thức Sườn cay khổng lồ và trà sữa Thái truyền thống."},{"day":2,"title":"Bangkok - Thành Phố Biển Pattaya - Chợ Nổi 4 Miền - Alcazar Show","desc":"Di chuyển đến Pattaya, tham quan Chợ nổi 4 miền đặc sắc bằng thuyền gỗ. Tối chiêm ngưỡng Alcazar Cabaret Show với ánh sáng và vũ điệu đỉnh cao thế giới."},{"day":3,"title":"Đảo San Hô Koh Larn Nước Trong Vắt - Trân Bảo Phật Sơn Khắc Vàng","desc":"Đi cano lướt sóng ra đảo Coral Koh Larn tự do tắm biển và dù lượn. Chiều viếng Núi Phật Vàng Khao Chee Chan được khắc bằng vàng 24K uy nghiêm."},{"day":4,"title":"Du Thuyền Trên Sông Chao Phraya - Viếng Chùa Bình Minh Wat Arun","desc":"Dạo thuyền trên dòng sông mẹ Chao Phraya huyền thoại ngắm cá nổi, check-in Chùa Bình Minh Wat Arun nguy nga tráng lệ và mua sắm tại IconSiam."},{"day":5,"title":"Đại Tiệc Buffet Tòa Nhà 86 Tầng Baiyoke Sky - Big C - Bay Về TP.HCM","desc":"Ăn buffet quốc tế tại tầng cao ngắm toàn cảnh Bangkok, mua sắm thỏa thích tại Big C Supercenter và xe tiễn đoàn ra sân bay về lại Việt Nam."}]', 1),

(6, 'TOUR-SIN-06', 'Tour Singapore Đảo Quốc Sư Tử - Thác Nước Jewel Changi - Gardens by the Bay', 'https://images.unsplash.com/photo-1525625293386-3f8f99389edd?w=600&h=400&fit=crop', 'Singapore Airlines Tour', 3, 'TP. Hồ Chí Minh', 'Singapore', 4, 3, '4N3Đ', '12:15', '2 giờ 05 phút', 'Boeing 787-10 Dreamliner', 10990000, 'Vé máy bay 5 sao Singapore Airlines khứ hồi, Khách sạn 4 sao trung tâm Orchard Road, Vé tham quan Khu vườn tương lai Gardens by the Bay, Vé tàu điện sang Đảo Sentosa, Thưởng thức tiệc Cua Sốt Ớt Chilli Crab trứ danh', 'Chi phí vé vào Universal Studios Singapore, Chi phí giặt ủi và đồ uống có cồn', '[{"day":1,"title":"TP.HCM - Sân Bay Quốc Tế Changi - Thác Nước Trong Nhà Khổng Lồ Jewel","desc":"Trải nghiệm dịch vụ bay 5 sao trên máy bay thân rộng Boeing 787-10. Hạ cánh Changi, chiêm ngưỡng thác nước Vortex 40m đẹp như tranh trong tổ hợp Jewel."},{"day":2,"title":"Công Viên Sư Tử Biển Merlion Park - Tòa Nhà Thuyền Marina Bay Sands","desc":"Chụp hình cùng biểu tượng Sư tử phun nước Merlion, dạo bước cầu Helix độc đáo, chiêm ngưỡng Marina Bay Sands và dạo phố cổ sầm uất Chinatown."},{"day":3,"title":"Siêu Cây Kỳ Ảo Gardens by the Bay - Đảo Giải Trí Sentosa","desc":"Lạc bước vào xứ sở tương lai với dàn siêu cây năng lượng Supertree Grove khổng lồ. Chiều qua đảo Sentosa check-in quả cầu xoay Universal Studios huyền thoại."},{"day":4,"title":"Khu Phố Đa Sắc Màu Haji Lane - Mua Sắm Đại Lộ Orchard - Bay Về TP.HCM","desc":"Khám phá nghệ thuật tranh tường graffiti tại Haji Lane, tự do mua sắm hàng hiệu miễn thuế tại Orchard Road trước khi ra sân bay Changi đáp chuyến bay về TP.HCM."}]', 1),

(7, 'TOUR-ICN-07', 'Tour Xứ Sở Kim Chi: Thủ Đô Seoul Năng Động - Đảo Nami Lãng Mạn - Công Viên Everland', 'https://images.unsplash.com/photo-1538485399081-7191377e8241?w=600&h=400&fit=crop', 'Vietjet Holidays', 1, 'Hà Nội', 'Seoul', 5, 4, '5N4Đ', '23:30', '4 giờ 15 phút', 'Airbus A330', 13990000, 'Vé máy bay khứ hồi Vietjet chặng bay đêm thoải mái, Khách sạn 4 sao Seoul, Vé trọn gói Đại công viên giải trí Everland, Vé phà sang Đảo Nami, Trải nghiệm mặc quốc phục Hanbok chụp ảnh tại Hoàng Cung, Bữa ăn thịt nướng BBQ Hàn Quốc và Gà hầm sâm thượng hạng', 'Chi phí visa du lịch Hàn Quốc, Tiền tip hướng dẫn viên địa phương', '[{"day":1,"title":"Hà Nội - Sân Bay Quốc Tế Incheon Seoul (Bay Đêm Nghỉ Ngơi)","desc":"Tập trung tại Nội Bài làm thủ tục đáp chuyến bay thẳng của Vietjet đến Incheon, nghỉ ngơi thư giãn trên tàu bay thân rộng Airbus A330."},{"day":2,"title":"Seoul - Đảo Nami Bối Cảnh Phim Bản Tình Ca Mùa Đông Bất Hủ","desc":"Chào đón bình minh xứ Hàn, xe đưa đoàn đi tham quan Đảo Nami thơ mộng với những hàng cây ngân hạnh và bạch dương thẳng tắp rợp bóng lãng mạn."},{"day":3,"title":"Cung Điện Hoàng Gia Gyeongbokgung - Làng Cổ Bukchon Hanok","desc":"Mặc trang phục truyền thống Hanbok bước vào Cung điện Gyeongbokgung cổ kính, tham quan Nhà Xanh Phủ Tổng thống và tản bộ qua những con ngõ bình yên tại Bukchon."},{"day":4,"title":"Oanh Tạc Đại Công Viên Everland - Thiên Đường Mua Sắm Myeongdong","desc":"Thỏa sức tham gia các trò chơi cảm giác mạnh tại Top 10 công viên giải trí thế giới Everland. Tối hòa mình vào thiên đường mỹ phẩm và street food Myeongdong."},{"day":5,"title":"Tháp Truyền Hình N Seoul - Mua Sâm Chính Phủ - Bay Về Hà Nội","desc":"Lên Tháp N Seoul ngắm nhìn toàn cảnh thành phố và lưu dấu ấn tại Cầu khóa tình yêu. Mua sắm nhân sâm chính phủ, nấm linh chi và ra sân bay Incheon bay về."}]', 1),

(8, 'TOUR-TYO-08', 'Tour Nhật Bản Mùa Hoa: Tokyo Sầm Uất - Núi Phú Sĩ Hùng Vĩ - Trải Nghiệm Tắm Onsen', 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?w=600&h=400&fit=crop', 'Vietnam Airlines Tour', 2, 'TP. Hồ Chí Minh', 'Tokyo', 6, 5, '6N5Đ', '06:00', '5 giờ 40 phút', 'Airbus A350-900', 24990000, 'Vé máy bay khứ hồi Vietnam Airlines 46kg ký gửi (2 kiện), Khách sạn 4 sao tiêu chuẩn Nhật Bản, 01 đêm nghỉ dưỡng resort và tắm khoáng nóng Onsen truyền thống, Thưởng thức thịt bò Wagyu nướng và Sushi tươi sống, Vé cáp treo ngắm Núi Phú Sĩ', 'Chi phí visa nhập cảnh Nhật Bản, Tiền bồi dưỡng HDV và tài xế (7$/ngày)', '[{"day":1,"title":"TP.HCM - Sân Bay Quốc Tế Haneda Tokyo - Nghỉ Ngơi Nhận Phòng","desc":"Đáp chuyến bay chất lượng cao của Vietnam Airlines đến thủ đô Tokyo nhộn nhịp. Xe đón về nhận phòng khách sạn 4 sao, tự do khám phá phố đêm."},{"day":2,"title":"Chinh Phục Núi Phú Sĩ Trạm Số 5 - Làng Cổ Thanh Bình Oshino Hakkai","desc":"Lên Trạm số 5 Núi Phú Sĩ chiêm ngưỡng ngọn núi biểu tượng của nước Nhật. Thăm làng cổ Oshino Hakkai dưới chân núi với những hồ nước trong vắt tan từ băng tuyết."},{"day":3,"title":"Trải Nghiệm Văn Hóa Tắm Suối Khoáng Nóng Onsen Cổ Truyền","desc":"Trải nghiệm phong tục tắm Onsen truyền thống tốt cho sức khỏe và sắc đẹp, thưởng thức bữa tối Kaiseki hoàng gia cùng rượu sake trứ danh xứ Phù Tang."},{"day":4,"title":"Chùa Cổ Asakusa Kannon - Tháp Tokyo Skytree - Phố Điện Tử Akihabara","desc":"Viếng ngôi chùa cổ nhất Tokyo Asakusa Kannon và dạo phố Nakamise. Check-in tháp truyền hình cao nhất thế giới Skytree và thiên đường anime Akihabara."},{"day":5,"title":"Giao Lộ Bận Rộn Nhất Thế Giới Shibuya - Mua Sắm Hàng Hiệu Ginza","desc":"Chụp hình cùng chú chó trung thành Hachiko tại giao lộ Shibuya huyền thoại, tự do mua sắm mỹ phẩm, đồ điện tử cao cấp tại khu phố thương mại xa hoa Ginza."},{"day":6,"title":"Vịnh Nhân Tạo Odaiba Ngắm Tượng Nữ Thần Tự Do - Bay Về TP.HCM","desc":"Tản bộ ngắm Cầu Cầu Vồng Rainbow Bridge và Tượng Nữ thần Tự do tại Vịnh Odaiba. Xe đưa ra sân bay Haneda đáp chuyến bay về lại TP. Hồ Chí Minh."}]', 1);

